// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(c.optimisticAsserter()));

        bytes32 assertionId = bytes32(uint256(1));
        bool ok;
        vm.prank(caller);
        try c.assertionDisputedCallback(assertionId) {
            ok = true;
        } catch {
            ok = false;
        }

        assertFalse(ok);
    }
}
